SELECT customers.id, customers.email, customers.age, t.expired_count, t.basic_monthly_fee FROM customers JOIN (SELECT customer_id, SUM(CASE WHEN status = 'EXPIRED' THEN 1 ELSE 0 END) AS expired_count, SUM(CASE WHEN plan = 'basic' THEN monthly_fee ELSE 0 END) AS basic_monthly_fee FROM subscriptions GROUP BY customer_id) t ON customers.id = t.customer_id WHERE t.basic_monthly_fee > 45 ORDER BY basic_monthly_fee DESC, id LIMIT 1;
